SELECT COUNT(*)
FROM tl_todo_tasks
WHERE user_id = #{userId}

  AND status = #{status}


  AND due_date >= #{from}


  AND due_date <= #{to}

SELECT task_id, user_id, title, status, due_date, created_at
FROM tl_todo_tasks
WHERE user_id = #{userId}

  AND status = #{status}


  AND due_date >= #{from}


  AND due_date <= #{to}

ORDER BY task_id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT task_id, user_id, title, status, due_date, created_at
FROM tl_todo_tasks
WHERE task_id = #{taskId}
  AND user_id = #{userId}
